def seg(kind, text, target=None):
    return {"type": kind, "description": text, "completion_criteria": "done", "target": target}


def nav(text="Go to the bench"):
    return seg("navigation", text, "bench")


def man(text):
    return seg("manipulation", text)


def lab(index, prim, *objs):
    return {"index": index, "primitive": prim, "objects": [{"phrase": p, "role": r} for p, r in objs]}


def raises(fn, text=""):
    try:
        fn()
    except PostprocessError as e:
        return text in str(e)
    except Exception:
        return False
    return False


